    if (nb > 0) {
        if (n_squared >= nb || n_squared == 0) {
            return (1);
        }
    } else if (-n_squared <= nb || n_squared == 0) {
        return (1);
    }
    if (nb == n || nb == -n) {
        return (1);
    }
    return (test_prime(nb, n + 1));
}

