    return -1;
}

static
int is_valid(char c, int has_started, int *is_neg, const char *base)
{
    if (index_in(c, base) != -1)
        return 1;
    if (c == '+')
        return !(has_started);
    if (c == '-') {
        if (has_started)
            return 0;
        *is_neg = !*is_neg;
        return 1;
    }
    if (has_started)
        return 0;
    *is_neg = 0;
    return 1;
}

static
int true_val(int res, int is_neg)
{
    if (is_neg)
        return res;
    res = -res;
    if (res < 0)
        return 0;
    return res;
}

