    int len = my_strlen(base);

    if (!str || !base)
        return 0;
    for (int i = 0; str[i]; i++) {
        if (is_valid(str[i], has_started, &is_neg, base) == 0)
            return true_val(res, is_neg);
        if (index_in(str[i], base) == -1)
            continue;
        has_started = 1;
        res = res * len + -index_in(str[i], base);
        if (res > 0)
            return 0;
    }
    return true_val(res, is_neg);
}

